	 ('01a18def-1bf8-74ff-9e42-47233e5838db','pt-BR','Você é tão linda que se fosse um arquivo de extensão, seria .HOT'),
	 ('01a18def-1bf8-7513-9a21-e46d8d56ecf6','pt-BR','Você conhece o feitiço Petrificus Totalus? Porque você me deixou duro'),
	 ('01a18def-1bf8-73a3-ab3e-af88c330c92f','pt-BR','Definitivamente, eu não sou o Gollum, mas você certamente é a minha preciosa'),
	 ('01a18def-1bf8-7d73-b322-4773aab2cae8','pt-BR','A varinha escolhe o bruxo e a minha escolheu você'),
	 ('01a18def-1bf8-72f0-9032-b6836d4b124b','pt-BR','Gata, posso invadir sua jungle?'),
	 ('01a18def-1bf8-79a9-8db9-96ae35340037','pt-BR','Eu não sou a Shireen, mas você tá me fazendo pegar fogo'),
	 ('01a18def-1bf8-7faf-94e0-0fa15787446d','pt-BR','Você é eletricista? Porque você iluminou o meu dia.'),
	 ('01a18def-1bf8-7575-b1a1-fc17e1d71787','pt-BR','Se beleza fosse flor, você seria o Jardim Botânico!"');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-705b-95bf-a06888e1d973','pt-BR','Quais heróis se preocupam mais com as poses para fotos do que com salvar o seu planeta?{br}Os TumblrCats'),
	 ('01a1a3bc-a138-7806-8d9e-8322faefbf6d','pt-BR','Qual é a profissão do Homem Aranha?{br}Desenvolvedor Web'),
	 ('01a1a3bc-a138-7cf7-822c-fd045dc6cc11','pt-BR','Qual é o estado dos EUA que te eletrifica?{br}Ohio.'),
	 ('01a1a3bc-a138-7152-90b7-887417d34c9d','pt-BR','Por que o monge foi ao hospital?{br}Porque ele é paciente.'),
	 ('01a1a3bc-a138-710b-a31b-5c9282ce356c','pt-BR','Qual o time mais quente de todos?{br}Bota-fogo.'),
	 ('01a1a3bc-a138-75a8-a944-96318537560c','pt-BR','Por que o cachorro ia pra escola todos os dias?{br}Porque ele tinha auaula.'),
	 ('01a1a3bc-a138-75d7-a558-be5634fcad35','pt-BR','Qual o produto tensoativo que sabe de tudo?{br}Sabão.'),
	 ('01a1a3bc-a138-7657-8b61-6fe1c426afe7','pt-BR','Quem é o rei dos produtos de espantar insetos?{br}É o Rei-pelente.'),
	 ('01a1a3bc-a138-7551-9794-ce82991a1984','pt-BR','Por que o magrelo tem que tomar banho com os braços abertos?{br}Para não ser engolido pelo ralo.'),
	 ('01a1a3bc-a138-746f-9af1-c72996f4a9c4','pt-BR','Qual o ator que livra as pessoas das dores?{br}Malvino Salva-dor.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7ea2-8828-bb957d3ebde9','pt-BR','Por que as vogais A, E, I e O foram rejeitadas pela banda Scorpions?{br}Porque eles Still Love U.'),
	 ('01a1a3bc-a138-758e-aa08-c3c7afd9e3cd','pt-BR','Qual a carne que é cheia de panos?{br}Frango Empanado.'),
	 ('01a1a3bc-a138-7591-9c4a-5b2758015e6e','pt-BR','Por que o Papai Noel não tem assadura?{br}Porque seu saco já é vermelho.'),
	 ('01a1a3bc-a138-7cfb-93de-c0449df85a83','pt-BR','Qual é a bebida que corre?{br}Rum.'),
	 ('01a1a3bc-a138-7826-bb68-e53754ab2491','pt-BR','Você está em uma estrada e vê vários postos um perto do outro. Por que isso acontece?{br}Porque os-postos se atraem.'),
	 ('01a1a3bc-a138-7f5a-b1b3-4fe91ce89dc1','pt-BR','Qual animal não gosta do amanhã?{br}Rinocer-ontem.'),
	 ('01a1a3bc-a138-760e-8c06-ddbe3821ffd6','pt-BR','O que acontece se um panda tiver vários filhotes?{br}Vira uma pandemia.'),
	 ('01a1a3bc-a138-7150-ad2a-39ed53f35a1f','pt-BR','Qual a fruta predileta da cigana?{br}O Li Mão.'),
	 ('01a1a3bc-a138-7909-9437-41af38635d9c','pt-BR','Qual é o tipo de música favorito dos mortos?{br}R.I.P-Hop.'),
	 ('01a1a3bc-a138-7f0d-b5f3-6a58e80263c3','pt-BR','O que é que tem no meio do ovo?{br}A gema.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-735e-adb0-b59e159f725f','pt-BR','Por que a loira entrou com muitos espelhos na faculdade de engenharia?{br}Porque ela é engenheira se-viu.'),
