	 ('01a1a3bc-a138-76fd-afd7-a19125033948','pt-BR','O que o leitão foi fazer na loja de parafusos?{br}Foi procurar a porca.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-70f3-82c3-4a0bb4ea82af','pt-BR','O que o boi respondeu para a vaca, quando ela o perguntou se ele gostava bastante dela?{br}Muuuuuuuuuuuuito!'),
	 ('01a1a3bc-a138-7ef4-b62c-d6632a7e239b','pt-BR','Como se chama o campeonato de anedotas?{br}Olim-piadas.'),
	 ('01a1a3bc-a138-75f9-af9c-101edf9d82ce','pt-BR','Qual a reação de um mecânico depois de contarem uma piada sem graça para ele?{br}Dizer que não achou graxa nenhuma.'),
	 ('01a1a3bc-a138-7286-a94e-2b01b6308477','pt-BR','Qual o tipo de violência que o super-herói do martelo não admite?{br}A Thortura.'),
	 ('01a1a3bc-a138-7971-b615-e41ba8203639','pt-BR','Qual a doença do sacristão?{br}Sinus-ite.'),
	 ('01a1a3bc-a138-7c8a-a3f4-3345662a1df5','pt-BR','Por que temos vacas e bois próximos ao nosso estômago?{br}Porque temos o intestino deu-gado.'),
	 ('01a1a3bc-a138-75d1-a723-f18ab6a03c57','pt-BR','Qual o tipo de pessoa o Papai Noel gosta?{br}De puxa-saco.'),
