	 ('01a1a3bc-a138-7017-85b3-36783d192e8d','pt-BR','Qual o carro em que o Cebolinha manda as pessoas pararem?{br}Ô-Pala.'),
	 ('01a1a3bc-a138-7b8d-a959-3cf15fbeb10b','pt-BR','Você sabe qual é a comida preferida do topógrafo?{br}Frângulo.'),
	 ('01a1a3bc-a138-7fda-9420-04c10b2836d3','pt-BR','Como se fala bombeiro em japonês?{br}Takágua Naxama.'),
	 ('01a1a3bc-a138-7c6b-ac0d-a8efca302bb7','pt-BR','Qual a rede social que os mineiros mais usam?{br}Uaitsapp.'),
	 ('01a1a3bc-a138-7efb-bce9-c1b5981a7e47','pt-BR','Qual é o nome da pedra falante?{br}Sei lá, question pra ela, ela fala!'),
	 ('01a1a3bc-a138-7211-9da7-87b8c5eee5c8','pt-BR','Qual é a massa do caderno?{br}A massa folhada.'),
	 ('01a1a3bc-a138-76ca-94de-48a74d613563','pt-BR','Três mulheres estavam com picolés nas mãos. Uma estava chupando o picolé, outra estava mordendo o picolé e outra estava lambendo o picolé. Qual delas era a casada?{br}A que estava com anel no dedo.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7051-af06-88f95614a076','pt-BR','Qual o banco em que uma letra se transforma em outra letra?{br}É o I-tá-U.'),
	 ('01a1a3bc-a138-745b-88cb-8d55565fe0fb','pt-BR','Qual a fruta que é parente da porta?{br}É a Maçã-Neta.'),
	 ('01a1a3bc-a138-71a5-8b83-9e3d47ab1eb1','pt-BR','Qual é a peça de roupa preferido do Thor?{br}PaleThor.'),
	 ('01a1a3bc-a138-7dd5-b62f-b6eb1939cf73','pt-BR','Qual a cantora que é o primeiro alce do mundo?{br}Alce-One.'),
	 ('01a1a3bc-a138-7dbb-a7d8-68a53de67ec9','pt-BR','Um bêbado estava na rua quando chegou um carro e buzinou. O que o bêbado respondeu?{br}Eu também bibi.'),
	 ('01a1a3bc-a138-7da7-b0e5-43dbba3fc1d2','pt-BR','Qual a diferença entre a cachaça e a mulher?{br}A cachaça dá dor de cabeça só um dia.'),
	 ('01a1a3bc-a138-724d-bbc8-c0256e92a4c5','pt-BR','Por que o português jogou o arroz inteiro do pacote dentro do pote de açúcar?{br}Para comer arroz doce.'),
	 ('01a1a3bc-a138-7d74-a124-5bf37b37abe4','pt-BR','Por que os lustres não prestam atenção para escuridão?{br}Porque eles tem focos luminosos.'),
	 ('01a1a3bc-a138-7115-b4fc-60f2bacee1f9','pt-BR','O que é um cachorro afinado, que entende de música?{br}É um cãotor.'),
	 ('01a1a3bc-a138-7f20-a22d-d21659f5b415','pt-BR','O que é um objeto cortante em poder de um cachorro?{br}Um cão-nivete.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-757e-85ec-a63c0bfb1328','pt-BR','Por que o maior dramaturgo de língua inglesa é considerado um cavalheiro quando tenta ir ao banheiro, mas está ocupado?{br}Porque quando ele bate e respondem que tem gente, ele diz em seguida: Shake-espera.'),
	 ('01a1a3bc-a138-7ce4-978d-f4b7521b1024','pt-BR','Por que na cidade de Palmas as mulheres nunca conseguem molhar o cabelo?{br}Porque lá elas usam Touca-ntins.'),
	 ('01a1a3bc-a138-77d3-845a-32ff18daba9a','pt-BR','Por que a loira pediu um envelope redondo no escritório onde trabalha?{br}Porque seu chefe a pediu para entregar uma circular.'),
	 ('01a1a3bc-a138-725e-8730-5d8012078c67','pt-BR','Qual o veículo que é mulher do lanche?{br}Lancha.'),
	 ('01a1a3bc-a138-76d1-9b9f-f73f713d3757','pt-BR','O tio de Pedro tem 4 filhas, Lala, Lele, Lili, Lolo. Qual falta?{br}Nenhuma, porque já tem 4.'),
	 ('01a1a3bc-a138-7172-b3d5-a985a57c6e39','pt-BR','Qual o molho de tomate preferido dos gatos?{br}É o Cat-chup.'),
	 ('01a1a3bc-a138-7682-aa67-b616d509e0ae','pt-BR','Qual o eletrodoméstico do vulcão?{br}É a máquina de lava.'),
	 ('01a1a3bc-a138-7388-971d-331535b66082','pt-BR','Um homem levou um pedaço de queijo pro hospício e um dos pacientes subiu em cima do queijo. Qual o nome da série?{br}Um Maluco no Pedaço.'),
	 ('01a1a3bc-a138-76be-bdc1-aac6d32d90dd','pt-BR','O que pensaram os outros convidados quando viram o Zangado chegar na festa sem a Branca de Neve?{br}Ah, Não!'),
	 ('01a1a3bc-a138-7f29-8598-cb294e1019a2','pt-BR','Qual o campeonato que tira as suas dores?{br}Liberta-dores');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7069-8f6f-7157e905eb3c','pt-BR','Qual é a vestimenta preferida do Batman?{br}Bat-ina.'),
	 ('01a1a3bc-a138-70d5-9f7e-092bd038c48e','pt-BR','Por que um atleta dormiu na balança de uma farmácia?{br}Para que quando acordasse fizesse um levantamento de peso.'),
	 ('01a1a3bc-a138-722b-8715-e1a8f50ef614','pt-BR','Qual o peixe que é parceiro de todo mundo?{br}Truta.'),
	 ('01a1a3bc-a138-770d-a576-6a033aae328f','pt-BR','Por que as roupas amassadas se estenderam sobre o trilho?{br}Porque lá passa o Trem de Ferro.'),
	 ('01a1a3bc-a138-7273-b7ec-f392cb8408c6','pt-BR','Qual o médico que as pessoas atiram compostos orgânicos?{br}Geraldo Álcool-Em-Mim.'),
	 ('01a1a3bc-a138-78a3-a967-369f2c71db02','pt-BR','Como se diz veterinário em japonês?{br}Kuragato Nakasa.'),
	 ('01a1a3bc-a138-7747-990d-cd6ea4e1fbba','pt-BR','Qual é o alimento preferida do Thor no natal?{br}Pane-Thor-ne.'),
	 ('01a1a3bc-a138-7c27-a879-b4633e0f37a7','pt-BR','Qual é o aparelho digital preferido do Thor?{br}LapTHORp.'),
	 ('01a1a3bc-a138-77fe-aa52-a8665f4a47b1','pt-BR','Por que a loira leva sabonete e shampoo pro pé de manga?{br}Porque ela gosta de tomar banho de mangueira.'),
	 ('01a1a3bc-a138-7bd1-aebc-cb311a5438f9','pt-BR','Qual a explosão que o Renato Aragão mais tem medo?{br}É a Didi-namite.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-78de-bdc8-689db270c5b9','pt-BR','O que a Oceania e a novela tem em comum?{br}Que a Oceania é O Outro Lado do Mundo e a novela é O Outro Lado do Paraíso.'),
	 ('01a1a3bc-a138-7227-88d7-dd255b137508','pt-BR','O menino estava assistindo desenho, e seu pai sem querer resvala na tomada e acaba desligando a TV. Qual o nome do desenho?{br}Pô-pai.'),
	 ('01a1a3bc-a138-7c87-8612-7ee2857d56f2','pt-BR','Qual é a fruta que termina primeiro do que todas as outras?{br}Jabuti-acaba.'),
	 ('01a1a3bc-a138-78b6-9de4-f3b112160f31','pt-BR','Qual é o urso que nunca envelhece?{br}Peter-Panda.'),
	 ('01a1a3bc-a138-7bae-bace-8befc8a6c30d','pt-BR','Porque o urso começou a se coçar de repente?{br}Porque ele era um urso empolar.'),
	 ('01a1a3bc-a138-7005-b41b-59dfd2a2bde3','pt-BR','Um americano perguntou para o bom velhinho do natal: Papai, o senhor está bem?{br}No well, respondeu o senhor...'),
	 ('01a1a3bc-a138-7653-843b-2586236535a8','pt-BR','O que disse uma pessoa após ter descoberto que havia comprado um óculos sem as lentes?{br}Cuidado, é armação...'),
	 ('01a1a3bc-a138-7382-8c7e-6952a1fc1d8a','pt-BR','Por que as senhoras que vão à piscina gostam tanto de Helmmans?{br}Porque elas só ficam de maiô-nesse.'),
	 ('01a1a3bc-a138-73f9-b2dc-8c9ec35475b0','pt-BR','Porque todos os tipos de carne não toleram os bifes macios?{br}Porque elas são contra-filé.'),
	 ('01a1a3bc-a138-71eb-adcc-7242d533199e','pt-BR','Qual o estado brasileiro que anda de trem?{br}Piauiiiiiiiiiiiiiiii.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7a52-b489-57fa5050090d','pt-BR','Como a família portuguesa que mora no Brasil parou de gastar com oftalmologista?{br}Mudando-se para Boa-Vista.'),
	 ('01a1a3bc-a138-7330-9b60-36d83c853731','pt-BR','Qual é a capital brasileira que ensina a irmã a latir?{br}Mana, au-aus.'),
	 ('01a1a3bc-a138-74c9-bc7b-4aa2370edca1','pt-BR','Qual a cidade mais amarela do mundo?{br}Yellows Angeles.'),
	 ('01a1a3bc-a138-7f22-940c-97b9e8e508d1','pt-BR','Qual é o cantor que poderia ser ortopedista?{br}Caetano Vê-o-osso.'),
	 ('01a1a3bc-a138-7222-a3eb-1ea7e319935a','pt-BR','Qual o carro mais azedo que existe?{br}Limão-zine.'),
	 ('01a1a3bc-a138-73d7-8d60-be470b417509','pt-BR','Por que um jardineiro estava cavando o chão da vila do Chaves?{br}Porque ele queria achar o tesouro.'),
	 ('01a1a3bc-a138-7534-8036-06a1c0f6dfcb','pt-BR','Qual o problema de saúde que nenhum anão terá?{br}Pressão alta.'),
	 ('01a1a3bc-a138-7539-8dbf-051eb854fcc1','pt-BR','Qual é a fruta favorita dos maquinistas?{br}Kiwiiiiiiiiiiiiiii!!!'),
	 ('01a1a3bc-a138-771f-a7dc-0ca274ddadf6','pt-BR','Qual é a fruta que ameniza o calor de Ana?{br}Abana-Ana.'),
	 ('01a1a3bc-a138-7807-8dff-38b8a44db1bd','pt-BR','Por que o estádo do Grêmio tem muitas abelhas?{br}Porque Pedro Gerou-o-mel.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7e3f-9370-d06b92aa146c','pt-BR','Dois textos eram incompletos e estavam participando de alguns campeonatos de futebol, o que um disse pro outro?{br}Precisamos de título.'),
	 ('01a1a3bc-a138-7aa1-b1ae-db2b4e64d8a5','pt-BR','Qual o apresentador que tem olfato de animal?{br}Rodrigo Faro.'),
	 ('01a1a3bc-a138-701a-8fef-4da271595852','pt-BR','Qual é o carro do exército?{br}Kadett.'),
	 ('01a1a3bc-a138-7f20-b869-ac3899b11bf8','pt-BR','Qual é a crença ou religião que está sempre conectada à internet?{br}A Umbanda Larga.'),
	 ('01a1a3bc-a138-70e5-8234-2ae42ba80f4c','pt-BR','Qual é o lugar da igreja que o Batman mais gosta?{br}Bat-istério.'),
	 ('01a1a3bc-a138-7be9-ac27-39a9540aaa1a','pt-BR','Qual é o animal preferido do Thor?{br}OrniThorrinco.'),
	 ('01a1a3bc-a138-7028-9fd0-8186c2d523be','pt-BR','Meu fim me leva ao começo ou o inexiste, sou um caminho sem fim, oque eu sou?{br}Um paradoxo.'),
	 ('01a1a3bc-a138-716c-bdc3-f376f40ed6d8','pt-BR','Estou à sua volta, moro em seu coração, mas não posso ser compartilhado. O que eu sou?{br}A solidão. Qualquer outro sentimento e até mesmo a sabedoria e conhecimento pode ser compartilhado.'),
	 ('01a1a3bc-a138-7d80-a2c0-8bad2332b3c9','pt-BR','Por que a loira comeu o telhado da casa?{br}Porque ela era comi-lona.'),
	 ('01a1a3bc-a138-7c83-a4a6-6fc76e432a61','pt-BR','Por que o anão não escuta o outro?{br}Porque ele fala baixinho.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7865-a391-85f6b9a00813','pt-BR','Qual o time de futebol em que um chinês observa um jogo de sinuca?{br}Lee-ver-pool.'),
	 ('01a1a3bc-a138-77d8-85fd-0dd5d18363fc','pt-BR','Qual o animal preferido do Renato Aragão?{br}Didi-nossauro.'),
	 ('01a1a3bc-a138-7597-9665-09b45419295d','pt-BR','Qual time de futebol larga na frente?{br}Na-Pole.'),
	 ('01a1a3bc-a138-7b60-a551-1734a53618ee','pt-BR','Qual a atriz que faz cópias de imagens?{br}Gisele Print.'),
	 ('01a1a3bc-a138-7f9c-80ba-c58f85e51e02','pt-BR','Qual o lugar onde as pessoas mais fazem churros?{br}Na enxurrada.'),
	 ('01a1a3bc-a138-7878-a6e3-bc74480659aa','pt-BR','Qual é a função do Thor?{br}CorreThor.'),
	 ('01a1a3bc-a138-74cf-82bc-6dd0c3d0e52e','pt-BR','Qual país que se você pisar, será preso?{br}Cana-dá.'),
	 ('01a1a3bc-a138-75bc-9bc3-d0f76227ee33','pt-BR','Um jogador de futebol apareceu e virou líder de um time de um programa de domingo da Globo. Qual o nome do filme?{br}Capitão Fantástico.'),
	 ('01a1a3bc-a138-70ac-bdd7-0fd441f4e4f1','pt-BR','O que o goleiro utiliza para dormir?{br}Trave-sseiro.'),
	 ('01a1a3bc-a138-7692-ac3a-72ba689c51c6','pt-BR','Qual o aparelho luminário preferido do Thor?{br}RefleThor.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7abf-ac74-4054f9892962','pt-BR','Qual o animal mais fuxiqueiro que existe?{br}A fo-foca.'),
	 ('01a1a3bc-a138-7504-b309-c5c9e1135362','pt-BR','Qual é o animal peçonhento que trabalha com montaria?{br}É o escor-peão.'),
	 ('01a1a3bc-a138-769f-b899-dc4edd5601f6','pt-BR','Por que um determinado inseto voador não reclama de aterrissar nos piores locais possíveis?{br}Por que Mari-pousa em qualquer lugar.'),
	 ('01a1a3bc-a138-7e3d-9902-70cbfffb339e','pt-BR','Qual é o nome da norma jurídica para pessoas com dificuldades de dicção por repetirem demais as sílabas das palavras?{br}Lei de Gaga.'),
	 ('01a1a3bc-a138-7e7a-b336-70e55224ab1e','pt-BR','Tinham dez pessoas em cima de uma árvore jogando pastilhas garoto nas pessoas que passavam em baixo. Qual o nome do filme?{br}Os Dez Manda Menta.'),
	 ('01a1a3bc-a138-7e55-9405-35171c1c8229','pt-BR','Qual o ovo mais escuro que existe?{br}Ovinho tinto.'),
	 ('01a1a3bc-a138-7d84-a68c-7acf30e045f9','pt-BR','Por que nunca falta energia no fundo do rio?{br}Porque ele tem enguia elétrica.'),
	 ('01a1a3bc-a138-7ce1-bbad-eed25957b7b8','pt-BR','Qual artista você não pode convidar para sua casa?{br}O Eric... Claptomaniaco!'),
	 ('01a1a3bc-a138-72f6-8b15-a66e07fad51f','pt-BR','Do que as velhinhas mas sentem saudades?{br}Da Ditadura!'),
	 ('01a1a3bc-a138-7da7-ba8d-22c666cd8b54','pt-BR','Qual a semelhança entre o Uruguai e o YouTube?{br}Que os dois tem um Monte-Vídeo.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7263-a676-d59b9aa6b1ce','pt-BR','No trânsito, como fazer para as dores corporais passarem mais depressa?{br}É só pisar no acelera-dor.'),
	 ('01a1a3bc-a138-7810-9503-759b294e7307','pt-BR','Por que o envelope é tão medroso jogando baralho?{br}Porque ele só guarda as cartas.'),
	 ('01a1a3bc-a138-7df0-8859-fd967f7a1c8e','pt-BR','Por que as roupas devem se pendurarem nos cabides?{br}Porque eles não tem mãos pra segurarem elas.'),
	 ('01a1a3bc-a138-7922-81a4-fc8bd3f37eab','pt-BR','Qual a vodka que da tiros para os dois lados?{br}Bala-lá-e-cá.'),
	 ('01a1a3bc-a138-7ac2-93b9-a25a40630321','pt-BR','Qual o chocolate que espanta que espanta a capital do Equador?{br}Xô-Quito.'),
	 ('01a1a3bc-a138-7432-a3d4-c3cea5fe23c4','pt-BR','Como se chama mil políticos presos?{br}Um bom começo.'),
	 ('01a1a3bc-a138-75f9-a2d1-53b889c1f905','pt-BR','O que desce chorando da escada?{br}Balde.'),
	 ('01a1a3bc-a138-76e1-8073-915e64500bd5','pt-BR','Por que o carro jamais é eletrocutado?{br}Porque ele tem o para-choque.'),
	 ('01a1a3bc-a138-7e1d-ae3b-fe91cbefd400','pt-BR','Qual é a versão de Dragon Ball que o Vasco, Fluminense e Botafogo mais gostam?{br}Kai.'),
	 ('01a1a3bc-a138-7ce9-9b11-1ffbad2a0da0','pt-BR','Qual é o mosquito que a vaca tem medo?{br}Muuuuriçoca.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7b50-beed-1a636a4f896d','pt-BR','Por que um tigre auxiliava o idoso a andar?{br}Porque ele era um tigre de bengala.'),
	 ('01a1a3bc-a138-7cc7-acd7-4f1b6cc36720','pt-BR','Quem é que, no Natal, anda com o saco cheio às costas subindo e descendo a rua?{br}O carteiro, ou você acredita em Papai Noel?'),
	 ('01a1a3bc-a138-74f1-8265-a5008a4467d6','pt-BR','Como um escritor termina um caso de amor?{br}Com um ponto final.'),
	 ('01a1a3bc-a138-71b7-a598-639070992f04','pt-BR','Por que é que "na casa do ferreiro tem espeto de pau"?{br}Porque "santo de casa não faz milagre".'),
	 ('01a1a3bc-a138-796c-bc1c-da66dd5510a0','pt-BR','Entre médicos, qual deveria ser considerado engenheiro?{br}Os que faz pontes de safena.'),
	 ('01a1a3bc-a138-7e11-b1fa-83ea5b04ba55','pt-BR','Quem é que bate na porta sem estar chamando ninguém?{br}O marceneiro.'),
	 ('01a1a3bc-a138-75af-8448-32779c171b84','pt-BR','Que fazem os grandes costureiros, quando não têm o que fazer?{br}Inventam moda.'),
	 ('01a1a3bc-a138-7103-a7f0-73eae079a334','pt-BR','Que pista levou o policial à certeza de que aquele carro, parado no estacionamento, era roubado?{br}O motor estava quente, mas a placa fria.'),
	 ('01a1a3bc-a138-768b-a3b0-1d441b4a76d1','pt-BR','Qual a profissão que aborrece?{br}A de amolador.'),
	 ('01a1a3bc-a138-7b46-9a82-5119413ed0c6','pt-BR','Como se chama o jornal do oculista?{br}O globo ocular.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7167-b528-6f1a4c538da5','pt-BR','Qual a carta que melhora a vida do carteiro?{br}A carta de recomendação.'),
	 ('01a1a3bc-a138-71f4-b3ef-fe84926a067a','pt-BR','Qual o produto alimentício preferido dos escritores?{br}A sopa de letrinhas.'),
	 ('01a1a3bc-a138-7cea-8a0c-6a46392b861e','pt-BR','Que escritor escreve um livro em menos de um minuto?{br}Qualquer um: "um livro".'),
	 ('01a1a3bc-a138-703e-be4d-3d20b8e70f0d','pt-BR','Qual o lugar onde o pescador pode até escolher o peixe?{br}Na peixaria.'),
	 ('01a1a3bc-a138-7cc8-9d06-ab3b91c99eff','pt-BR','Por que um astrônomo sempre se frusta quando tenta estudar os grandes grupos de estrelas do Universo?{br}Porque no telescópio, a visão é sempre nebulosa.'),
	 ('01a1a3bc-a138-78cd-8593-f6907d1c1ffe','pt-BR','Quem é que se encarrega pessoalmente de transmitir os nossos desabafos, as nossas alegrias, exigências e consulta sem jamais ter contato conosco?{br}O carteiro.'),
	 ('01a1a3bc-a138-72e9-b605-bc1db9d0956e','pt-BR','Qual é a capital preferida do Thor?{br}PreTHORia.'),
	 ('01a1a3bc-a138-7a27-87a0-c65475e398e4','pt-BR','Qual a prótese que vive durante um longo período?{br}É a denta-dura.'),
	 ('01a1a3bc-a138-717a-9e70-b574f9630d5d','pt-BR','Qual a haste de metal que é uma operadora de TV?{br}É o Alfi-NET.'),
	 ('01a1a3bc-a138-7800-82ba-b94dc104b372','pt-BR','Onde o Renato Aragão nasceu?{br}Na Didi-namarca.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-71a6-8b01-5811cb449b46','pt-BR','Qual o país que sai pegando tudo?{br}Catar.'),
	 ('01a1a3bc-a138-71a6-8852-e227964614b8','pt-BR','Por que a música foi na papelaria?{br}Porque ela queria um clipe.'),
	 ('01a1a3bc-a138-7eb5-ac4b-9f98c4101f43','pt-BR','No salão de beleza, por que o português colocou uma grade sobre a cabeça?{br}Porque ele queria um de-gradê.'),
	 ('01a1a3bc-a138-72e0-99e2-991633596748','pt-BR','Qual o jogador que trata água?{br}Aguero.'),
	 ('01a1a3bc-a138-72ca-acb1-acff6f9b2d22','pt-BR','Qual é o jogador que não toma tiro?{br}Dybala.'),
	 ('01a1a3bc-a138-768d-b4d8-6e0fee120f66','pt-BR','Qual país do caribe é uma explosão?{br}Granada.'),
	 ('01a1a3bc-a138-7bd7-81e3-03054d65e55d','pt-BR','Nas obras, como fazer para a parede de tijolo ser recarregada?{br}É só fazer um abaste-cimento.'),
	 ('01a1a3bc-a138-7ac5-8ac1-41eb23efbe65','pt-BR','Qual o ator que os operários sobem em cima dele?{br}Vã-Andaime.'),
	 ('01a1a3bc-a138-756b-a8b3-25cb90411642','pt-BR','O que acontece se o coqueiro beber demais?{br}Ele chapa o coco.'),
	 ('01a1a3bc-a138-7e14-bc22-e1bf383c3dbe','pt-BR','Estou acima das pessoas mais posso ficar a baixo delas, sou sólido e essencial para um lar quem eu sou?{br}Terraço.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7c24-9f77-d13f1ee028ee','pt-BR','O que um jogador de futebol falou pro outro na hora de dar um pré-datado?{br}Eu não tenho dinheiro, mas o Peter Cheque.'),
	 ('01a1a3bc-a138-7208-b51c-e6d40753a359','pt-BR','O que a ponte pequena disse para outra que cresceu?{br}E agora, eu te vi-adulto.'),
	 ('01a1a3bc-a138-7d20-9c7b-47984a0e18a5','pt-BR','Por que o fio sentiu frio?{br}Porque ele estava desencapado.'),
	 ('01a1a3bc-a138-7ffc-be78-98dac71e660b','pt-BR','Qual é a cerveja favorita dos cachorros?{br}Glaciau-au.'),
	 ('01a1a3bc-a138-74f8-90d3-c02829aa131b','pt-BR','Qual é o animal mais preguiçoso que existe?{br}A dor-minhoca.'),
	 ('01a1a3bc-a138-773e-9bbb-abedcec4562c','pt-BR','Qual é o movimento que as próprias pessoas que curtem muito realizam?{br}Fã-farra.'),
	 ('01a1a3bc-a138-7145-9a44-eeefe2db75ca','pt-BR','Por que o energético mais conhecido do mundo agora faz propaganda de marca de informática?{br}Porque Red Bull te dá Asus!'),
	 ('01a1a3bc-a138-791a-aad8-6f9235604fd8','pt-BR','Qual é o pão que o Ursinho Pooh mais gosta?{br}Pão de Mel.'),
	 ('01a1a3bc-a138-7da5-87ae-7abb123da696','pt-BR','Qual é o brinquedo preferido do Thor?{br}AuTHORama.'),
	 ('01a1a3bc-a138-7e1b-b06a-1251ff012f3f','pt-BR','Qual o conselho que o seu pai te dava para classificar as mulheres por tipo?{br}Cate-gurias.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7d93-bbe8-019a87357710','pt-BR','Qual é a fruta que é também é dois animais?{br}Jabuti-Cabra.'),
	 ('01a1a3bc-a138-7cfb-8890-18e55ed055b0','pt-BR','Represento o amor, mas amor não posso ter, me desenham com 2 indicadores, mas como um punho da sua mão eu posso ser, que sou eu?{br}O coração.'),
	 ('01a1a3bc-a138-7f6f-bf02-b14d4a9eee48','pt-BR','O que o pobre tem que se o rico comer ele morre?{br}Nada. O pobre tem nada, e se o rico comer nada ele morre de fome.'),
	 ('01a1a3bc-a138-7733-a25f-644d43631a01','pt-BR','Qual atriz é um peixe cartilaginoso?{br}Claudia Arraia.'),
	 ('01a1a3bc-a138-7083-bc2c-00e342fc0004','pt-BR','Qual a planta dos sentimentos imediatos?{br}Jacinto.'),
	 ('01a1a3bc-a138-7746-a236-122ab66ca672','pt-BR','O que é que diz um ratão de 100 quilos?{br}Vem, vem gatinho.'),
	 ('01a1a3bc-a138-7b62-97c6-81e2796e96a9','pt-BR','O que é que se pede com o dedo?{br}Ligação telefônica.'),
	 ('01a1a3bc-a138-7baf-a2d6-65e93b25d8d3','pt-BR','O que é que perdido uma vez nunca mais se acha?{br}O tempo.'),
	 ('01a1a3bc-a138-7d02-9dfe-5125b00a3506','pt-BR','Para que homem todos os outros tiram o chapéu?{br}Para o barbeiro.'),
	 ('01a1a3bc-a138-7d9e-8bb9-c3527e6f96bc','pt-BR','Qual a palavra que você usa quando se esquece das outras?{br}Sinônimos.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7e3a-b0d5-70f89527fbe6','pt-BR','O que nasce grande e morre pequeno?{br}O sabão.'),
	 ('01a1a3bc-a138-7583-b5f8-0f011895c9e9','pt-BR','O que é o que é entra na igreja de cabeça para baixo?{br}O prego do sapato.'),
	 ('01a1a3bc-a138-791d-97c6-e92879ed5f38','pt-BR','Qual o jogador de basquete que trabalha como faxineiro?{br}Anderson Varre Chão.'),
	 ('01a1a3bc-a138-798d-9bb2-d222c26462ec','pt-BR','Qual banda de rock que beija todo mundo?{br}Kiss.'),
	 ('01a1a3bc-a138-78eb-bfd7-de86b6189393','pt-BR','Qual o cantor que se compara com as leis marítimas?{br}Bob Mar-Lei.'),
	 ('01a1a3bc-a138-7fdb-868f-16827f1d5ff9','pt-BR','Qual o aplicativo preferido do Thor?{br}Play sThor.'),
	 ('01a1a3bc-a138-7c43-935e-828742d26e09','pt-BR','Qual a flor que diz estar se sentindo?{br}Jacinto.'),
	 ('01a1a3bc-a138-7742-880f-0262404c028d','pt-BR','Qual ator é símbolo de países?{br}Antônio Bandeiras.'),
	 ('01a1a3bc-a138-7c53-8202-fa2b5d8f36ee','pt-BR','Qual o planeta mais admirado do supermercado?{br}Uau-Marte.'),
	 ('01a1a3bc-a138-70c2-bd3c-798dc0a73664','pt-BR','Qual a batata que todos devem respeitar?{br}Lays.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-71d6-921d-9ef63b8f4348','pt-BR','Qual o hipermercado preferido do número 4?{br}Carre-Four.'),
	 ('01a1a3bc-a138-715e-8c6b-d2e8a520f524','pt-BR','Qual a universidade particular que quase tira um dez?{br}Uni-nove.'),
	 ('01a1a3bc-a138-75f1-9aa1-9e26efe3bd97','pt-BR','Qual a diferença entre um limão e o Mr. Bean?{br}Que o limão só faz careta quando é chupado.'),
	 ('01a1a3bc-a138-75ff-8110-a65e88d61216','pt-BR','Qual a cerveja que os de menores não podem beber?{br}Proibida.'),
	 ('01a1a3bc-a138-72b9-bbdb-2129fd632a9e','pt-BR','Qual o salgadinho que mais vai no jogo de futebol?{br}A Torcida.'),
	 ('01a1a3bc-a138-73b5-bfe6-2324473cd0f8','pt-BR','O que um bolo com frio disse pro outro?{br}Precisamos de cobertura.'),
	 ('01a1a3bc-a138-7021-ae20-e005246feb19','pt-BR','Por que o armário estava lotado?{br}Porque todos queriam ver o jogo de panelas.'),
	 ('01a1a3bc-a138-7c9d-ba48-4a0b4b1dc19a','pt-BR','Por que Bob Marley é folgado?{br}Porque ele quer que o arrasta-fari.'),
	 ('01a1a3bc-a138-789a-a8e2-89b811562d92','pt-BR','Tenho 5 maçãs, roubo de Joãozinho 5, quantas tartarugas tem no pote de doce?{br}Duas, pois vassoura não assiste TV a noite.'),
	 ('01a1a3bc-a138-74a5-8f19-d4c663a62316','pt-BR','Qual animal mais gosta de cantar em grupo?{br}A cobra-coral.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7803-8ebf-b01de0b46938','pt-BR','Por que os padres amam açúcar?{br}Porque eles abraçam um sacer-doce-o.'),
	 ('01a1a3bc-a138-739f-83f7-4618da897469','pt-BR','Qual é a comida favorito da piranha?{br}Pirão.'),
	 ('01a1a3bc-a138-777b-baee-dbc59b90a2db','pt-BR','O que uma ave perguntou pra outra sobre o futebol?{br}Meu time é o Flamingo, e o seu?'),
	 ('01a1a3bc-a138-77c8-8b3c-656b0e5677de','pt-BR','Por que um dos maiores apresentadores da Rede Globo não queria uma fazenda?{br}Porque ele queria apenas uma Chacrinha.'),
	 ('01a1a3bc-a138-7a7b-8fbd-e685df54e5a7','pt-BR','Qual a doença que mais incomoda os gaúchos?{br}Artri-tchê.'),
	 ('01a1a3bc-a138-75b5-97f8-d03943e56004','pt-BR','Por que Angelina não é considerada uma atriz completa?{br}Porque para isso, Angelina além de Jô-Li, deveria ser Jô-Escrevi também.'),
	 ('01a1a3bc-a138-7ba7-8917-f998b317f66a','pt-BR','Por que o ex-marido de Angelina Jolie é considerado um cara muito chato?{br}Porque vive o Brad dando Pití.'),
	 ('01a1a3bc-a138-71ad-a4ce-904170027f87','pt-BR','Qual é o veículo de comunicação que sempre obverva você?{br}É a Rede Te Vê.'),
	 ('01a1a3bc-a138-780d-ae7a-d7ddf2cd2780','pt-BR','Por que nos montes mais altos e frios da Suíça tem cachorros?{br}Porque lá estão os au-aupes.'),
	 ('01a1a3bc-a138-7107-870e-0ef837798a32','pt-BR','Qual é o legume favorito do menino de madeira que cresce o nariz?{br}O Pepinóquio.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-74f7-90f8-34af9e9d66a9','pt-BR','Qual a fruta que tem título de nobreza?{br}Fruta-do-Conde.'),
	 ('01a1a3bc-a138-72c8-9d2c-10772517a720','pt-BR','Por que o português colocou a cama no guarda-roupas?{br}Por que o médico o pediu para guardar leito.'),
	 ('01a1a3bc-a138-76da-b9e3-2ba430b3fe37','pt-BR','O que o mineirinho pediu ao saber que no cardápio de um determinado restaurante só servia frutos do mar?{br}Uma banana d''água.'),
	 ('01a1a3bc-a138-7f3f-8c67-860fd8ff3948','pt-BR','Qual é o país onde as pessoas mais praticam musculação?{br}Só-malha.'),
	 ('01a1a3bc-a138-78b0-9d6a-5fc3540071a6','pt-BR','Qual é o animal que mais sente quando a temperatura está alta?{br}A Calor-psita.'),
	 ('01a1a3bc-a138-7a93-9d03-81fd0e2d9930','pt-BR','Qual animal é o melhor dos dançarinos?{br}O tatu-re-bola.'),
	 ('01a1a3bc-a138-762e-be7d-357f7ed39c21','pt-BR','Qual o celular que deixa você fazer o que quiser com ele?{br}Ai pode.'),
	 ('01a1a3bc-a138-7dfe-8f7b-f70b154c685d','pt-BR','Por que a roupa saiu correndo e pulou na banheira d''água?{br}Porque ela só levava ferro.'),
	 ('01a1a3bc-a138-7151-b746-149ffb47da7a','pt-BR','Por que um homem vivia cheio de velas em sua casa?{br}Porque ele era fã do Caetano Veloso.'),
	 ('01a1a3bc-a138-7d9d-88d6-53bdc975cc9b','pt-BR','Por que a galinha gorda estava batendo a cabeça no bebedouro elétrico?{br}Porque ela queria um galão.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7c41-940d-d001a690ad18','pt-BR','Qual é a profissão agente do Thor?{br}CorreThor.'),
	 ('01a1a3bc-a138-7b33-b5fa-22dba13a4e28','pt-BR','O que o Thor mais gosta do banheiro?{br}Thor-alha.'),
	 ('01a1a3bc-a138-717c-ac18-21c46332595f','pt-BR','Qual é a função de autoridade do Thor?{br}PromoThor.'),
	 ('01a1a3bc-a138-7e14-abf3-56d8e70b320a','pt-BR','Qual o jogador que larga as coisas de qualquer jeito?{br}Se-dane.'),
	 ('01a1a3bc-a138-7798-b5ac-53c1f0aa34c7','pt-BR','Por que a vaca foi pra Alemanha?{br}Porque ela queria ver Muuuuu-nique.'),
	 ('01a1a3bc-a138-77c1-a374-c767f7d9b1a8','pt-BR','Por que a loira joga o relógio pela janela?{br}Porque a hora voa.'),
	 ('01a1a3bc-a138-7b23-b3b2-0945e5287a03','pt-BR','Por que o Médico tem a letra feia?{br}Porque ele não sabe escrever, só prescrever.'),
	 ('01a1a3bc-a138-7c61-b138-6c083ab4e424','pt-BR','O que o gato faz quando está na rua?{br}Engatinha.'),
	 ('01a1a3bc-a138-7113-9ea7-24a2d1bdd8ae','pt-BR','Por que os cães da Austrália ficam roucos?{br}Porque a capital do país se chama cão-berra.'),
	 ('01a1a3bc-a138-7394-8001-f2743bb82ddf','pt-BR','Por que os papéis e as folhas tem medo do Rio de Janeiro?{br}Porque eles fazem picadinho.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7df9-87c2-4a042bb7794a','pt-BR','Qual a ave que quer matar as vacas imediatamente em busca de seu couro?{br}Couro-já.'),
	 ('01a1a3bc-a138-784b-8603-11ce1e250a9c','pt-BR','Qual é a Lua que nunca esta com fome?{br}Lua cheia.'),
	 ('01a1a3bc-a138-7c65-8309-f589ada14c5b','pt-BR','O que tem cara de um lado e animal do outro?{br}As notas.'),
	 ('01a1a3bc-a138-795a-bb4a-b9f4cf4e2ad3','pt-BR','Segunda pessoa do singular; Água passa; Qual é o nome do animal?{br}TUcano.'),
	 ('01a1a3bc-a138-7bec-af9e-e0d39d423ed8','pt-BR','Eu tenho um cachorro que se chama Choco. O que Choco faz?{br}CHOCO-late.'),
	 ('01a1a3bc-a138-7ac4-b0b0-8ba3881061d7','pt-BR','Ge estava andando de bicicleta, mas ele não viu a ladeira que estava à sua frente. O que falaram para ele?{br}Ge-Ladeira.'),
	 ('01a1a3bc-a138-7c60-83a4-9a1c98dcc5f7','pt-BR','O que o tempo e a novela tem em comum?{br}O tempo é o Senhor da Razão, e a novela é a Senhora do Destino.'),
	 ('01a1a3bc-a138-7acb-88d7-3ec9069ebefd','pt-BR','Por que parente e igual a dente?{br}Porque quanto mais afastado melhor pra não juntar sujeira.'),
	 ('01a1a3bc-a138-7707-95b4-fcd7460854a9','pt-BR','Qual o país dos touros?{br}Bull-Garia.'),
	 ('01a1a3bc-a138-79f2-ab78-e481be24bb3c','pt-BR','Qual a cantora que abre todas as portas?{br}Kelly Key.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7f6b-ab79-1488059f6748','pt-BR','Por que os torcedores estavam com a mão na cara?{br}Por que os atletas iam jogar tênis.'),
	 ('01a1a3bc-a138-7ecd-905b-78e5ec6db126','pt-BR','Por que as abelhas não comem pão de sal?{br}Porque elas já têm o pão de mel.'),
	 ('01a1a3bc-a138-706a-b714-4081c86513dd','pt-BR','Nas novelas, como fazer para os atores vovôs falarem mais alto?{br}É só apertar o vô-lume.'),
	 ('01a1a3bc-a138-7716-b7a3-04245c209eb3','pt-BR','Por que os camaleões mudam de cor sozinho?{br}Porque eles não precisam de lápis de cor.'),
	 ('01a1a3bc-a138-75bc-b4a4-dda27d1c7fc5','pt-BR','Qual a comida que tem um grupo de soldados prontos para guerra?{br}Feijão Tropeiro.'),
	 ('01a1a3bc-a138-70af-9dee-0ad4d94899f6','pt-BR','Por que os baianos não deixam nada aberto?{br}Porque eles tem o vatampá.'),
	 ('01a1a3bc-a138-7eaa-a424-973eb8d4a31d','pt-BR','Qual o ator que mais gosta de flores?{br}Tony Ramos.'),
	 ('01a1a3bc-a138-7491-a8d0-cfb8594a7c00','pt-BR','Qual a atriz mais enxuta?{br}Deborah Secco.'),
	 ('01a1a3bc-a138-7c85-808c-06dbe46964d4','pt-BR','Qual o santo do Rodrigo?{br}São Toro.'),
	 ('01a1a3bc-a138-7001-8cae-f4fe7356887f','pt-BR','Qual enfermidade tem o técnico da seleção brasileira de futebol quando entra em um labirinto?{br}Labirin-Tite.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-77d5-8a8e-04d4cf6d83c8','pt-BR','Qual o jogador que só vive com raiva?{br}Bravo.'),
	 ('01a1a3bc-a138-75f6-a5de-b61eadd6c254','pt-BR','O que todo homem faz quando está no banheiro?{br}Sai do banheiro.'),
	 ('01a1a3bc-a138-78aa-bae6-59bd9836acc8','pt-BR','Por que o nadador jogou a televisão na piscina?{br}Para fazer um nado sintonizado.'),
	 ('01a1a3bc-a138-7788-9622-0e56f387ae1f','pt-BR','Por que o italiano tem que se equilibrar jogando xadrez?{br}Porque senão ele perde sua torre.'),
	 ('01a1a3bc-a138-7f2c-b97b-67728d0364a9','pt-BR','Por que a cama do sabão facilmente estoura?{br}Porque seu colchão é de espuma.'),
	 ('01a1a3bc-a138-752a-9363-7d8052dc8634','pt-BR','Qual é o eletrodoméstico preferido do Batman?{br}Bat-deira.'),
	 ('01a1a3bc-a138-7028-9e27-33b9d7e3f7e1','pt-BR','Qual comida que quase tira um 10?{br}Strogo-nove.'),
	 ('01a1a3bc-a138-7f12-9143-b8e85a50d636','pt-BR','Qual o brinquedo preferido do McDonald''s?{br}McSteel.'),
	 ('01a1a3bc-a138-762f-9082-ef610612b537','pt-BR','O que a vaca foi fazer na papelaria?{br}Comprar uma muuuuuuuu-chila.'),
	 ('01a1a3bc-a138-756d-8231-517365899075','pt-BR','Qual o material escolar que mostra a parte de seu corpo que dói?{br}Aponta-dor.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7ae7-b635-4ed4318f79b3','pt-BR','Qual a rede social mais gorda?{br}InstaGrama.'),
	 ('01a1a3bc-a138-7296-99af-dd0928ebc801','pt-BR','Qual é o tipo de festa que os cegos frequentam?{br}O braille funk.'),
	 ('01a1a3bc-a138-764f-9924-39646c6e0b7c','pt-BR','Por que no Rio de Janeiro as pessoas não comem pão de sal?{br}Porque eles têm o Pão de Açúcar.'),
	 ('01a1a3bc-a138-7f5b-b706-3d7b3999f39d','pt-BR','Qual super herói tira foto no escuro?{br}Flash.'),
	 ('01a1a3bc-a138-746d-8056-151ffcbd93d9','pt-BR','Quando está apaixonado, como um sabão em pó se declara?{br}Eu te OMO.'),
	 ('01a1a3bc-a138-7d77-b1b5-d51b5e7a2335','pt-BR','O que a mãe açaí disse para os outros açaís?{br}O último açaí feche a porta.'),
	 ('01a1a3bc-a138-7850-8c35-1eb288b0bab3','pt-BR','Qual é o carro que gosta de fazer exercícios?{br}Cooper.'),
	 ('01a1a3bc-a138-7a92-8469-8c80b034e54e','pt-BR','Por que o pai do Thor é um ser pré-histórico?{br}Porque ele é Odinossauro.'),
	 ('01a1a3bc-a138-7302-a5d6-d1cb19bf8a99','pt-BR','O que o Batman faz com o celular?{br}Bat-Selfie.'),
	 ('01a1a3bc-a138-7a30-aa85-7a45a2fe40ac','pt-BR','Qual o contrário de futsal?{br}Fut-açúcar.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-76bf-834a-38968534406c','pt-BR','Como seria o nome chinês do preguiçoso?{br}Kan-sei ou kochi-lin.'),
	 ('01a1a3bc-a138-775a-bb91-39a07eb74d02','pt-BR','Por que o relógio é popular?{br}Porque ele é da hora.'),
	 ('01a1a3bc-a138-7176-8a79-eaf2625ad70c','pt-BR','Por que a piada da bola é a melhor?{br}Porque ela é bem bolada.'),
	 ('01a1a3bc-a138-7066-9f1f-d817cc08b03c','pt-BR','Qual é o traficante que toma uma gelada no boteco?{br}Pablo Skol Bar.'),
	 ('01a1a3bc-a138-77f8-8392-631536581383','pt-BR','O que tem 5 cordas e uma cova?{br}Violão.'),
	 ('01a1a3bc-a138-7544-9df6-2bd20a1857ee','pt-BR','Qual o santo da Ivete?{br}São Galo.'),
	 ('01a1a3bc-a138-7c81-b642-922524bc0c24','pt-BR','Qual é o chocolate dos gatos?{br}Kit-Cat.'),
	 ('01a1a3bc-a138-79a5-9c63-64cedcdf0223','pt-BR','Qual o esporte preferido dos gaúchos?{br}Basquetchê.'),
	 ('01a1a3bc-a138-7506-bd3b-68905b999084','pt-BR','Quem é o rei da farmácia?{br}Rei-médio.'),
	 ('01a1a3bc-a138-7707-b54f-40f4633e60e2','pt-BR','Qual o contrário de buscapé{br}Levamão.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-72f2-8400-900a16426371','pt-BR','Qual o carro mais amado da Julieta?{br}Alfa-Romeu.'),
	 ('01a1a3bc-a138-79ad-a4b6-281b580698f0','pt-BR','Qual a cerveja preferida dos mineiros?{br}Bud-Uai-Zé.'),
	 ('01a1a3bc-a138-7c5e-9b42-269401900cd7','pt-BR','Por que a Holanda não cresce?{br}Porque ela é um País-Baixo.'),
	 ('01a1a3bc-a138-715b-8230-93586843d0fe','pt-BR','Qual o contrário de cachorro-quente?{br}Cadela fria.'),
	 ('01a1a3bc-a138-709c-a328-59473f866441','pt-BR','Por que o frango atravessou a rua?{br}Porque era dia de folga da galinha.'),
	 ('01a1a3bc-a138-73aa-a80d-7347f8abd3d7','pt-BR','Por que o Thor é rico?{br}Porque ele tem O-din-din.'),
	 ('01a1a3bc-a138-7fa6-9a4d-ff2436943060','pt-BR','O que é o quê é e branco não é líquido e serve pra bebê?{br}Fralda.'),
	 ('01a1a3bc-a138-7463-b73c-0fbddb99b1d7','pt-BR','Qual é o veículo que lava roupas?{br}Tanque.'),
	 ('01a1a3bc-a138-7c9d-a073-481a4a0cb8c4','pt-BR','Qual é a área de ensinamentos do Thor?{br}Or-THOR-grafia.'),
	 ('01a1a3bc-a138-757f-8473-a5a36689e0cd','pt-BR','O que o Thor mais gosta de contar?{br}His-THOR-ia.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7f09-8e3b-9f1e8df66080','pt-BR','Qual é o veículo mais sacana?{br}Velo-troll.'),
	 ('01a1a3bc-a138-7c50-9a12-cac068b63e98','pt-BR','O que é um grande prédio com apenas uma janela?{br}Agulha.'),
	 ('01a1a3bc-a138-7863-a5e0-09135a5d3980','pt-BR','O que é que é que no interior é uma linda praia e fora um mato?{br}Coco.'),
	 ('01a1a3bc-a138-7da3-804e-a4f688b1d696','pt-BR','Qual é a parte mais feminina da casa?{br}JanELA.'),
	 ('01a1a3bc-a138-7240-8cd0-ea5bb165229e','pt-BR','Por que o Batman é tão ruim nos jogos de carta?{br}Porque ele só pega coringa.'),
	 ('01a1a3bc-a138-74c3-a1df-3f4dc5ccdb5e','pt-BR','Qual é o contrário de contramão?{br}Favorpé.'),
	 ('01a1a3bc-a138-76f7-9076-c17e0c960ba8','pt-BR','Qual é o barco que sempre está aceso no escuro?{br}Barco a vela.'),
	 ('01a1a3bc-a138-724f-8a35-a61476dfc6d9','pt-BR','Qual o contrário de papelada?{br}Pá vestida.'),
	 ('01a1a3bc-a138-7cae-9472-1e1fd27eeda2','pt-BR','Qual a ave que é marca de bicicleta?{br}Caloi-picita.'),
	 ('01a1a3bc-a138-78ac-829a-4fb1d28a6668','pt-BR','Qual é o alimento mais sagrado do mundo?{br}Amén-doim.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7f74-99f4-1d0f1e0d5e24','pt-BR','Como o Thor se comunica com os outros Vingadores?{br}Por Thor-pedo.'),
	 ('01a1a3bc-a138-7610-b054-c9b1918e78db','pt-BR','Qual a parte mais sonora do corpo?{br}Rádio.'),
	 ('01a1a3bc-a138-7396-9dc6-3bad78493016','pt-BR','Qual e o esporte mais salgado?{br}Fut-sal.'),
	 ('01a1a3bc-a138-7982-95cc-f95817233fe2','pt-BR','Por que o vaso é o melhor presente para se ganhar?{br}Porque ele é de-coração!'),
	 ('01a1a3bc-a138-7331-9fe2-587cc8bcc778','pt-BR','O que o coelho disse quando se assustou?{br}Ah, minha nossa cenoura!'),
	 ('01a1a3bc-a138-7d38-bd11-4928ddbfdc7a','pt-BR','Qual é o hidrocarboneto da raiva?{br}Bicarbonato de ódio.'),
	 ('01a1a3bc-a138-7f6c-9744-41d291bfbf90','pt-BR','Por que o macaco tem medo de martelo?{br}Porque ele é um macaco-prego.'),
	 ('01a1a3bc-a138-77d2-87aa-bcdbd9f2d18a','pt-BR','Por que o jogador não estava conseguindo ligar do campo?{br}Porque ele estava fora de área.'),
	 ('01a1a3bc-a138-701c-bc2c-a65f1c161eb6','pt-BR','Qual o maior órgão público de uma cidade?{br}Orelhão.'),
	 ('01a1a3bc-a138-77b5-9ecc-f52f3df13e9f','pt-BR','O que o astronauta foi fazer no teclado?{br}Andar no espaço.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7509-833c-3a1bc7a01f42','pt-BR','Quais são os bandidos mais horríveis que existem?{br}Os ma-feiosos.'),
	 ('01a1a3bc-a138-7824-95c3-0cac41a98a8e','pt-BR','Qual carro está sempre ligado?{br}On-ix.'),
	 ('01a1a3bc-a138-7c75-809a-57e376f63186','pt-BR','Por que um caminhoneiro nunca consegue pegar uma garota no deserto?{br}Porque é muita areia pro seu caminhão.'),
	 ('01a1a3bc-a138-76fe-aca5-53f08924ac5f','pt-BR','Por que a chuva sempre cai sem nos avisar?{br}Porque ela é precipitada.'),
	 ('01a1a3bc-a138-7718-8320-fd919621287e','pt-BR','O que é o que é que depois de ficar muito tempo na geladeira continua quente?{br}Pimenta.'),
	 ('01a1a3bc-a138-7933-b770-71955dab0c2c','pt-BR','João tinha nove carrinhos, emprestou quatro para o Arthur. Com quantos carrinhos João ficou?{br}Continuou com nove, pois ele emprestou, ele não deu.'),
	 ('01a1a3bc-a138-7c1e-9511-ac23f6422f2a','pt-BR','O que é o que quando bate na pedra não quebra e quando cai na água se parte?{br}O papel.'),
	 ('01a1a3bc-a138-7237-911b-8ff008a904d9','pt-BR','Qual é o tipo de bebida preferida dos animais?{br}As de garrafa PET.'),
	 ('01a1a3bc-a138-7d8f-bf3b-208edb5b60d9','pt-BR','Qual é o prato preferido dos mecânicos?{br}Macarrão parafuso.'),
	 ('01a1a3bc-a138-7b77-9d27-3658f61c217b','pt-BR','Qual é a prisão, onde todos nós estamos condenados a passar?{br}Prisão de ventre.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7a31-acec-acb697c4828e','pt-BR','Um homem lá vinha com uma carroça, e na carroça tinha um burro, um capim e uma onça. A ponte estava quase quebrando, e ele tinha que atravessar uma coisa de cada vez, e sem deixar um comer ao outro. Que processo ele iria fazer?{br}Ele leva o burro e deixa ele lá, volta e busca a onça, traz o burro de volta e leva o capim, depois leva o burro de novo.'),
	 ('01a1a3bc-a138-7e67-9792-5c32d4acd817','pt-BR','Qual é a fruta preferida do Thor?{br}THORanja.'),
	 ('01a1a3bc-a138-77f3-89d8-9524a9600d85','pt-BR','Qual é o animal de estimação do Thor?{br}THOR-upeira.'),
	 ('01a1a3bc-a138-72fb-b32a-463e0c3791f4','pt-BR','Qual é a comida mais devagar?{br}A po-lenta.'),
	 ('01a1a3bc-a138-712c-92ed-ad168f7696be','pt-BR','Por que a menina doente foi pra a academia?{br}Pra ficar sarada.'),
	 ('01a1a3bc-a138-7a15-98d3-fed582d3484f','pt-BR','Com qual gênero a matemática combina?{br}Mulheres, pois são difíceis.'),
	 ('01a1a3bc-a138-757e-ab88-eac266e88862','pt-BR','O que o milho disse para a pipoca?{br}HuMILHO mesmo.'),
	 ('01a1a3bc-a138-7db0-b78a-7de030b52b27','pt-BR','Qual é o doce preferido do Thor?{br}Thorrone.'),
	 ('01a1a3bc-a138-738c-ae51-6038ee7ce6a7','pt-BR','Qual é o prato preferido do Thor?{br}Thorresmo.'),
	 ('01a1a3bc-a138-79ae-b8e5-910b681c741a','pt-BR','O que o Thor faz quando corta o dedo?{br}Thorniquete.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7743-8ead-f808d99cab2b','pt-BR','O que acontece se o Thor assoprar?{br}THORnado.'),
	 ('01a1a3bc-a138-7483-ac62-918bbc0db4ac','pt-BR','Quantas pata tem uma pata?{br}Somente uma, se fosse mais seria patapatapatapata...'),
	 ('01a1a3bc-a138-7662-bb28-af7d931099d9','pt-BR','Qual é a semelhança entre aranha e escorpião?{br}Com nenhum dos dois dá pra fazer bolo de abacate.'),
	 ('01a1a3bc-a138-7db6-b06a-59af410ceec9','pt-BR','Meu avô tem 4 filhos, cada filho tem 4 filhos. Quantos primos eu tenho?{br}12. Três são meus irmãos e um sou eu.'),
	 ('01a1a3bc-a138-7938-a1e3-03d661e498ee','pt-BR','Ela tinha 4 filhos. Janeiro, Fevereiro, Março. Qual é o nome do quarto filho.{br}O nome da criança e "Qual".'),
	 ('01a1a3bc-a138-7ca7-aed8-e494ac4b9f84','pt-BR','Qual o esporte que os cientistas gostam?{br}Fórmula 1.'),
	 ('01a1a3bc-a138-7ad1-bcb5-694104756c50','pt-BR','Qual a profissão histórica do Thor?{br}His-THOR-iógrafo.'),
	 ('01a1a3bc-a138-75a9-82bc-adc4e0fcfdc1','pt-BR','Qual a catástrofe que o Thor tem medo?{br}TerremoTHOR.'),
	 ('01a1a3bc-a138-725e-8857-510746dafc3e','pt-BR','O que o gato faz quando está na rua?{br}Engata.'),
	 ('01a1a3bc-a138-7d0c-a3ce-91bb57febcf6','pt-BR','Qual é a profissão do Thor?{br}Mo-THOR-ista.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7bfe-96a2-802910cc9502','pt-BR','Qual a especialização do Thor?{br}PaTHORlogia.'),
	 ('01a1a3bc-a138-7974-a89d-71d903b32a34','pt-BR','Qual a profissão secreta do Thor?{br}InspeThor.'),
	 ('01a1a3bc-a138-7b82-a5ea-199c3165477c','pt-BR','Qual é o frango que está sempre na mesa?{br}O frango alinamesa.'),
	 ('01a1a3bc-a138-7d42-8281-97a2a0d16415','pt-BR','Qual é a profissão do Thor?{br}Thoreiro.'),
	 ('01a1a3bc-a138-7f7b-971d-ac40c468522f','pt-BR','Qual o pão que o Thor mais come?{br}O THORrado.'),
	 ('01a1a3bc-a138-7233-97a5-c9210370c59d','pt-BR','No carro estavam 1 avó, 2 pais, 2 filhos e 1 neto. Quantas pessoas estavam no carro?{br}3 pessoas.'),
	 ('01a1a3bc-a138-74db-8ed9-2605aedad437','pt-BR','O que é surdo e mudo mas conta tudo?{br}Livro.'),
	 ('01a1a3bc-a138-748b-8674-c904a15407be','pt-BR','Por que a fração não cabe em uma casa?{br}Por que ela tem 4 quarto.'),
	 ('01a1a3bc-a138-79bc-a163-cd8f64434afb','pt-BR','Qual a parte do corpo que Thor mais gosta?{br}Thornozelo.'),
	 ('01a1a3bc-a138-7e66-ad56-afbd312b947f','pt-BR','O que o zero disse para o seis?{br}Nossa, apertou tanto o cinto que abriu a boca.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7648-b75c-ce7f6f269ac0','pt-BR','Qual e o animal que mais gosta de jogar futebol?{br}GOLfinho.'),
	 ('01a1a3bc-a138-7717-8966-44576321737f','pt-BR','Qual é o carro que só anda bem vestido?{br}Blazer.'),
	 ('01a1a3bc-a138-7f77-8687-187ac00e18e5','pt-BR','Por que guarda de trânsito é o ser mais forte do mundo?{br}Porque ele pode parar carros só com uma das mãos.'),
	 ('01a1a3bc-a138-7ac8-9c16-b07ef0a89100','pt-BR','Qual é o fenômeno que acontece no mar que o Thor tem medo?{br}Thormenta.'),
	 ('01a1a3bc-a138-7cd4-a444-d3beeee06cf9','pt-BR','Qual é o animal que mais gosta de jogar futebol?{br}O goooooooooolfinho.'),
	 ('01a1a3bc-a138-781d-b9b2-3e373a06c262','pt-BR','Tinha um pontinho verde no Xbox, qual é o nome do jogo?{br}Assassins GreenD.'),
	 ('01a1a3bc-a138-75ae-ae1a-9b6cb9cbef3b','pt-BR','Por que não podemos levar cães pros Estados Unidos?{br}Porque lá fura-cão.'),
	 ('01a1a3bc-a138-7ed7-8ce5-82e03dc44348','pt-BR','Qual é o país feminino?{br}VenezuELA.'),
	 ('01a1a3bc-a138-7e21-9ad6-6754fd59276c','pt-BR','Qual a meditação que se faz acordado?{br}ONnnn...'),
	 ('01a1a3bc-a138-7e86-84f0-1575e3381db4','pt-BR','O que a legume é do filho do filho dela?{br}Avóbora.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7833-93d8-ea99d79cf912','pt-BR','O que o zero dise para o oito?{br}Nossa, que cinto apertado!'),
	 ('01a1a3bc-a138-7180-acaa-8b525274b2ba','pt-BR','O que passa por todas as casas mas não sai do lugar?{br}A rua.'),
	 ('01a1a3bc-a138-70c8-8bd6-d7e42bc95afb','pt-BR','Cinco políticos estavam em uma lancha que acabou virando no meio do mar. Você sabe como salvá-los?{br}Não? Perfeito!'),
	 ('01a1a3bc-a138-7cde-8838-a7b8be6c619d','pt-BR','Qual é o bicho que anda com as patas?{br}O pato.'),
	 ('01a1a3bc-a138-77ad-8a5c-41262fcb138d','pt-BR','O que o Thor gosta de ser no tempo livre?{br}Fo-THOR-grafo.'),
	 ('01a1a3bc-a138-719a-9b75-35a47050b14b','pt-BR','Por que as mulheres não sentem frio?{br}Porque elas estão cobertas de razão.'),
	 ('01a1a3bc-a138-7370-b40d-3c0470e06137','pt-BR','Por que em Minas Gerais não tem mar?{br}Porque lá eles rezam livrai-nos de todos os mar.'),
	 ('01a1a3bc-a138-7e48-80c1-5a40ea88ff70','pt-BR','Qual o animal que a gordinha não quer encontrar de jeito nenhum quando fica magra?{br}O ex-quilo.'),
	 ('01a1a3bc-a138-7a52-82ec-6aedc9215ba0','pt-BR','Quem é a mãe da cozinha?{br}A mãezena.'),
	 ('01a1a3bc-a138-7cda-9d88-2120f476c372','pt-BR','O que o Thor usa nos pés para não se machucar enquanto corre?{br}Thor-nozeleiras.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7109-b7ce-cb314f5acc65','pt-BR','Qual o doce favorito do Thor?{br}Thortuguita.'),
	 ('01a1a3bc-a138-74aa-b5ec-7bdd58f13fd7','pt-BR','Do que o Thor faz parte?{br}Da Thorcida.'),
	 ('01a1a3bc-a138-7c41-840e-d68597579dd0','pt-BR','O que Michael Phelps disse para Sócrates?{br}Só sei que nadar sei.'),
	 ('01a1a3bc-a138-778c-9a18-0b9974da5105','pt-BR','O que o Batman mais sente no peito?{br}Bat-mentos.'),
	 ('01a1a3bc-a138-737e-b314-c2e5c8ba1eb8','pt-BR','Por que  o filho do joalheiro estuda tanto?{br}Pra ser um adulto joia.'),
	 ('01a1a3bc-a138-7eae-bb2e-21a940be25c2','pt-BR','Por que o surfista não gosta da cozinha?{br}Porque lá só tem micro-ondas.'),
	 ('01a1a3bc-a138-7192-ad9a-bef1abd0e5e0','pt-BR','Qual é o time preferido do Thor?{br}Thorino.'),
	 ('01a1a3bc-a138-730c-a48d-298319eeafc2','pt-BR','Qual é a cidade preferida do Thor?{br}Thoronto.'),
	 ('01a1a3bc-a138-7943-8225-9e241c61b4ad','pt-BR','Qual é a parte do quarto que o Thor mais gosta?{br}Thormada.'),
	 ('01a1a3bc-a138-71b4-8833-2afbe709d5a2','pt-BR','O que acontece se colocarmos sal em um boi bem pequeno?{br}Vira um sal-gadinho.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7e5c-8b75-19dd0779dfa8','pt-BR','O que até o mais pobre de todos tem?{br}Nome.'),
	 ('01a1a3bc-a138-7457-bb26-d8d047955ada','pt-BR','Quantas sílaba tem a palavra Trissílaba?{br}Uma, se fosse mais seria Trissílabasílabasílaba...'),
	 ('01a1a3bc-a138-7c98-b00a-24d803d7e450','pt-BR','O que para ser direito tem que ser torto?{br}Anzol.'),
	 ('01a1a3bc-a138-72b4-8630-d4396d3b3b43','pt-BR','Qual o remédio que contém álcool e gasolina?{br}Dorflex.'),
	 ('01a1a3bc-a138-70ff-98dc-323a5cf516bb','pt-BR','Qual é o animal favorito dos pintores?{br}Onça pintada.'),
	 ('01a1a3bc-a138-7c41-8d8d-fb170b833873','pt-BR','Qual a especialidade de Thor?{br}OrTHORpedista.'),
	 ('01a1a3bc-a138-78fb-8a25-d599e4f436b7','pt-BR','Qual o tênis quer ser uma majestade?{br}Rainha.'),
	 ('01a1a3bc-a138-7efa-a9ae-cd9501cc2ca8','pt-BR','Qual é o corte de cabelo preferido do Thor?{br}THORpete.'),
	 ('01a1a3bc-a138-7f4a-93aa-08de2da9f6a7','pt-BR','Qual a semelhança de um sapo e uma vassoura?{br}Com nenhum dos dois dá pra fazer pastel.'),
	 ('01a1a3bc-a138-7dd9-9688-584a4724ed49','pt-BR','Qual a Profissão preferida do Thor?{br}THORpógrafo.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7ad0-8535-8c53d4502334','pt-BR','Qual é a luta dos Gaúchos?{br}KaraTCHÊ.'),
	 ('01a1a3bc-a138-725a-8d3a-a97dae2a29f9','pt-BR','Qual é o carro movido a suco?{br}MusTANG'),
	 ('01a1a3bc-a138-71dc-83fb-a87f7e28d43c','pt-BR','Qual é a roupa preferido do macaco?{br}Macacão.'),
	 ('01a1a3bc-a138-7aaf-9ad2-c88cdfcbab0a','pt-BR','Qual é o fenômeno da Natureza que o Thor tem medo?{br}Thornado.'),
	 ('01a1a3bc-a138-73d5-81df-28782bc59605','pt-BR','Qual a cidade do Thor?{br}Thórquio.'),
	 ('01a1a3bc-a138-79f0-985f-426874337899','pt-BR','Tenho 40 laranjas, tiro 20. Quantas laranjas eu tenho?{br}Eu sabia isso com maçãs.'),
	 ('01a1a3bc-a138-718d-bed9-ba4e97854fdd','pt-BR','Qual a cantora que mais gosta de rir?{br}Ri-hanna.'),
	 ('01a1a3bc-a138-77e3-85fa-1e1cafaeddf3','pt-BR','Qual a parte do corpo do Thor que ele mais gosta?{br}THORax.'),
	 ('01a1a3bc-a138-7d14-a85a-fe55428bccbf','pt-BR','Qual a cantora gosta muito de tomar chá?{br}Chá-quira.'),
	 ('01a1a3bc-a138-702e-aa66-b25b7cc943d6','pt-BR','Tenho cinco laranjas, João roubou três. Quantas laranjas eu tenho?{br}Cinco.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-72c4-913b-4c1d21d3c4f7','pt-BR','Qual é a semelhança de uma dentadura e um chifre?{br}Ambos machucam mas acostumam.'),
	 ('01a1a3bc-a138-7143-8a2e-7048e00c41ef','pt-BR','Qual é o fruto preferido do Thor?{br}Thormate.'),
	 ('01a1a3bc-a138-7b55-85cc-dfc93f6d01e5','pt-BR','Qual é a atriz preferida do tamanduá?{br}Vera Farmiga'),
	 ('01a1a3bc-a138-77f6-a41c-83ce7bce510a','pt-BR','Qual o time o Thor torce?{br}Thorttenham.'),
	 ('01a1a3bc-a138-7755-a063-a81c304aa5ca','pt-BR','Quando foi a primeira vez que os povos da América comeram carne?{br}Quando chegou Cristóvão Com-lombo.'),
	 ('01a1a3bc-a138-7ad1-95a6-d3a7b08d82a0','pt-BR','Qual é o carro está sempre chateado?{br}Bravo.'),
	 ('01a1a3bc-a138-7878-a9c3-808e08898fc7','pt-BR','Por que na floresta tem sal?{br}Porque ela é temperada.'),
	 ('01a1a3bc-a138-72c2-95da-cb7df6dfe86c','pt-BR','O que o Mickey foi fazer no espaço?{br}Procurar o pai do seu cachorro, o Plutão.'),
	 ('01a1a3bc-a138-70c8-9535-d37e45b748a5','pt-BR','Por que a loira tomou o remédio antes da hora certa?{br}Pra pegar a doença de surpresa!'),
	 ('01a1a3bc-a138-7185-9964-8083d91978bc','pt-BR','Qual é a parte do banheiro que o Thor mais gosta?{br}Da Thorneira.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-7ce6-ae73-7fe1efeeddf8','pt-BR','Qual é a cidade preferida do tamanduá?{br}Formiga.'),
	 ('01a1a3bc-a138-7c33-9b03-bbcd5c1b8897','pt-BR','Qual é o país preferido no Natal?{br}Peru.'),
	 ('01a1a3bc-a138-742c-a1f2-2a39559004c9','pt-BR','Qual é a tinta que quer ser uma cobra?{br}Coral.'),
	 ('01a1a3bc-a138-7e07-8cc6-85b0930d7cf1','pt-BR','Qual é a cidade preferida do Thor?{br}Thórquio.'),
	 ('01a1a3bc-a138-7d8c-b091-a8c8e42d1f17','pt-BR','O que o pastel falou para o outro pastel?{br}Estamos fritos.'),
	 ('01a1a3bc-a138-7f25-883b-1a203c201f72','pt-BR','Hoje não tenho valor, mas já vali muito. O que sou?{br}História.'),
	 ('01a1a3bc-a138-7127-a343-267413688b40','pt-BR','O que nasce uma vez, nasce duas vezes, mas na terceira não nasce mais?{br}Dente.'),
	 ('01a1a3bc-a138-7682-9c0b-108cbf79bc9a','pt-BR','Em qual estado brasileiro as pessoas mais gostam de tomar suco?{br}Rio Grande do Suco.'),
	 ('01a1a3bc-a138-7baa-bba8-ea6affc88ec9','pt-BR','O que o aluno fala para a professora e gosta de receber dos pais?{br}Presente.'),
	 ('01a1a3bc-a138-79d6-b4f9-9b8282394147','pt-BR','O que acontece se um ciclista entrar em campo?{br}Ele faz um gol de bicicleta.');
INSERT INTO jokes (id,locale,"content") VALUES
	 ('01a1a3bc-a138-74bd-a349-f4f7ed747984','pt-BR','Qual é o estado preferido do Thor?{br}THORcantins.'),
	 ('01a1a3bc-a138-75de-a676-831a6e1aceca','pt-BR','Nunca para frente, sempre para trás, para crianças sou muito devagar, para adultos fui rápido demais. O que sou?{br}Infância.'),
	 ('01a1a3bc-a138-7a89-9ddf-94d088265adb','pt-BR','Nos vire ao avesso, e abra nossas vísceras, você será o mais sábio dos homens, mas, sem nós, será um idiota. O que sou?{br}Livro.'),
	 ('01a1a3bc-a138-7a92-86bd-96dd10749e50','pt-BR','De mim, surge vida, para mim, a vida retorna. Homens brigam pela minha posse, mas nenhum deles é meu dono. Água me cerca, mas ao redor dela eu vivo. Quem sou eu, meu amigo?{br}Terra.'),
	 ('01a1a3bc-a138-724a-94f2-174ad2780263','pt-BR','Assisti ao nascimento de reis e rainhas, meus pés vão mais fundo e minha cabeça mais alto do que tudo que o homem cria. Muitos buscam algo no interior do meu coração, mas, amor, não é algo que encontrarão, como vocês me chamarão?{br}Montanha.'),
	 ('01a1a3bc-a138-7b8a-854a-1cf7bc8d7c4e','pt-BR','Por que os robôs nao sentem medo?{br}Porque eles têm nervos de aço.'),
	 ('01a1a3bc-a138-7769-a6b5-2f5ff92c766a','pt-BR','Qual é estado que gosta de cavar buracos?{br}Ama-pá.');